func GetItems(chunks []*Chunk, n int) []Item {
	items := make([]Item, 0, n)
	for _, chunk := range chunks {
		for i := 0; i < chunk.count && len(items) < n; i++ {
			items = append(items, chunk.items[i])
		}
		if len(items) >= n {
			break
		}
	}
	return items
}

